const glyphPool = new Map();                      // FlyweightFactory

function glyph(font, size, color) {
  const key = `${font}:${size}:${color}`;
  let fw = glyphPool.get(key);
  if (!fw) {
    fw = Object.freeze({ font, size, color });    // intrinsic state
    glyphPool.set(key, fw);
  }
  return fw;
}
